  `import { Memo } from "@/types/proto/api/v1/memo_service";`
  `export async function loadMemos(): Promise<Memo[]> { ... fetch("/api/v1/memos?pageSize=100"), throw on !ok, map data.memos through Memo.fromPartial with displayTime new Date(String(...)) ... }`
  `export function selectMemos(memos: Memo[], _params: URLSearchParams): Memo[] { return memos; }`
