For the summary window:
```ts
function makeSummary(content: string, snippet: string, q: string): string {
  const base = content || snippet || "";
  const query = q.trim();
  if (!query) {
    return snippet || (base.length > 200 ? base.slice(0, 200) + "…" : base);
  }
  const idx = base.toLowerCase().indexOf(query.toLowerCase());
  if (idx === -1) {
    // q matched content, so should be found in content; but if not, fallback
    return base.length > 200 ? base.slice(0, 200) + "…" : base;
  }
  const start = Math.max(0, idx - 40);
  const end = Math.min(base.length, idx + query.length + 60);
  return (start > 0 ? "…" : "") + base.slice(start, end) + (end < base.length ? "…" : "");
}
```

