import { Memo } from "@/types/proto/api/v1/memo_service";

export async function loadMemos(): Promise<Memo[]> {
  const response = await fetch("/api/v1/memos?pageSize=100");
  if (!response.ok) throw new Error("Memos unavailable");
  const data = await response.json();
  return (data.memos || []).map((memo: unknown) =>
    Memo.fromPartial({
      ...(memo as Memo),
      displayTime: (memo as Memo).displayTime
        ? new Date(String((memo as Memo).displayTime))
        : undefined,
    }),
  );
}

function trimmed(param: string | null): string {
  return (param ?? "").trim();
}

export function selectMemos(memos: Memo[], params: URLSearchParams): Memo[] {
  const query = trimmed(params.get("q"));
  const tag = trimmed(params.get("tag"));

  return memos.filter((memo) => {
    if (query) {
      const content = (memo.content ?? "").toLowerCase();
      if (!content.includes(query.toLowerCase())) return false;
    }
    if (tag) {
      const target = tag.toLowerCase();
      const entries = (memo.tags ?? []).map((entry) => entry.toLowerCase());
      if (!entries.includes(target)) return false;
    }
    return true;
  });
}

export function summarizeMemo(memo: Memo, query: string): string {
  const content = memo.content ?? "";
  if (!query) {
    const base = memo.snippet || content;
    return base.length > 200 ? `${base.slice(0, 200)}…` : base;
  }
  const lower = content.toLowerCase();
  const index = lower.indexOf(query.toLowerCase());
  if (index === -1) {
    return content.length > 200 ? `${content.slice(0, 200)}…` : content;
  }
  const start = Math.max(0, index - 40);
  const end = Math.min(content.length, index + query.length + 60);
  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${end < content.length ? "…" : ""}`;
}
```

