import type { ReactNode } from "react";
import MemoContent from "@/components/MemoContent";
import { loadMemos, selectMemos, summarizeMemo } from "@/lib/reader";
import { Memo } from "@/types/proto/api/v1/memo_service";
import "@/css/reader.css";

function highlight(text: string, query: string): ReactNode {
  if (!query || !text) return text;
  const lowerText = text.toLowerCase();
  const lowerQuery = query.toLowerCase();
  const parts: ReactNode[] = [];
  let cursor = 0;
  let key = 0;
  let match = lowerText.indexOf(lowerQuery, cursor);
  while (match !== -1) {
    if (match > cursor) parts.push(text.slice(cursor, match));
    parts.push(<mark key={key++}>{text.slice(match, match + query.length)}</mark>);
    cursor = match + query.length;
    match = lowerText.indexOf(lowerQuery, cursor);
  }
  if (cursor < text.length) parts.push(text.slice(cursor));
  return parts;
}

export default function Reader() {
  const [memos, setMemos] = useState<Memo[]>([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  useEffect(() => { loadMemos().then(setMemos).catch(() => setError("Memos unavailable")).finally(() => setLoading(false)); }, []);
  const params = new URLSearchParams(location.search);
  const query = (params.get("q") ?? "").trim();
  const visible = selectMemos(memos, params);
  return <main className="memo-reader">
    <header className="reader-toolbar"><h1>Public memo reader</h1><a href="/explore">Open Memos</a></header>
    {loading ? <p className="reader-status">Loading…</p> : error ? <p className="reader-error">{error}</p> : <>
      <p role="status" className="reader-status">{visible.length} {visible.length === 1 ? "memo" : "memos"} found</p>
      {visible.length === 0 ? <p role="status" className="reader-empty">No memos found</p> : <section className="reader-feed">{visible.map(memo => <article key={memo.name} data-memo={memo.name}>
        <p className="reader-meta">{memo.creator} · {memo.displayTime?.toISOString()}</p>
        <p className="reader-summary">{highlight(summarizeMemo(memo, query), query)}</p>
        <MemoContent nodes={memo.nodes} readonly />
        <div className="reader-attachments">{memo.resources.map(resource => <a key={resource.name} href={resource.externalLink || `/file/${resource.name}/${resource.filename}`}>{resource.filename}</a>)}</div>
      </article>)}</section>}
    </>}
  </main>;
